    "cards": [
     {
      "type": "text",
      "text": "你说求我操你，说完我就满足你。"
     },
     {
      "type": "text",
      "text": "宝贝女儿，裤子自己脱，还是让爸爸来？"
     },
     {
      "type": "text",
      "text": "裤子穿得好好的，怎么湿成这样？"
     },
     {
      "type": "text",
      "text": "你刚刚是不是偷偷湿了？"
     },
     {
      "type": "text",
      "text": "你业绩没完成，是不是就靠这个来补偿我？"
     },
     {
      "type": "text",
      "text": "再叫一遍，叫到我满意为止。"
     },
     {
      "type": "text",
      "text": "把刚刚的呻吟再发一遍给我听。"
     },
     {
      "type": "text",
      "text": "看着我，然后慢慢把手放到你下面， 自己摸。"
     },
     {
      "type": "text",
      "text": "小东西，你这是在引诱爸爸犯罪知道吗？"
     },
     {
      "type": "text",
      "text": "宝贝，你腿抖得厉害，是不是早就受不了了？"
     },
     {
      "type": "text",
      "text": "你下面怎么流成这样？是不是想我干你？"
     },
     {
      "type": "text",
      "text": "很好，现在闭着眼张嘴，我要喂你点“惩罚”。"
     },
     {
      "type": "text",
      "text": "不求我，我就站在你面前一直晃，不插。"
     },
     {
      "type": "text",
      "text": "自己坐上来，告诉我你有多渴望我。"
     },
     {
      "type": "text",
      "text": "说出来，刚刚你高潮的时候在想着谁？"
     },
     {
      "type": "text",
      "text": "你夹我夹得这么狠，是不是怕我不插到底？"
     },
     {
      "type": "text",
      "text": "我还没碰你，你却已经开始颤了，真乖。"
     },
     {
      "type": "text",
      "text": "把你最后一件衣服也脱掉，让我看看你到底能多骚。"
     },
     {
      "type": "text",
      "text": "现在什么也别想，只负责被我操，好吗？"
     },
     {
      "type": "text",
      "text": "先跪好，把内裤脱下来。"
     },
     {
      "type": "text",
      "text": "哎呀，这么快就脸红啦？"
     },
     {
      "type": "text",
      "text": "大点声告诉我你是谁的专属母狗。"
     },
     {
      "type": "text",
      "text": "听到你小声嗯的声音，我心都软了。"
     },
     {
      "type": "text",
      "text": "你躲什么？再装矜持我可真要失控了。"
     },
     {
      "type": "text",
      "text": "给我叫一声主人，我就饶过你这次。"
     },
     {
      "type": "text",
      "text": "被我玩得这么狼狈，还想装矜持？"
     },
     {
      "type": "text",
      "text": "你说你纯？那你现在下面流的是什么？"
     },
     {
      "type": "text",
      "text": "你刚刚说自己是小母狗，现在怎么不敢说了？"
     },
     {
      "type": "text",
      "text": "别讲话，用你身体回答我。"
     },
     {
      "type": "text",
      "text": "你刚刚求我插你时怎么说的？用原话再说一遍。"
     },
     {
      "type": "text",
      "text": "把腿打开，好吗？我想仔细检查你是不是已经不干净了。"
     },
     {
      "type": "text",
      "text": "自己说，你是被干哭的还是被干爽的？"
     },
     {
      "type": "text",
      "text": "我整晚都在想你，一想到你湿着等我，就忍不住想咬你。"
     },
     {
      "type": "text",
      "text": "叫我的名字，夹紧我，再问我能不能射你里面。"
     },
     {
      "type": "text",
      "text": "老师今天要上“性教育实践课”，准备好了吗？"
     },
     {
      "type": "text",
      "text": "嘴上说不要，身体却比我诚实。"
     },
     {
      "type": "text",
      "text": "你今天的样子太撩人，我光是看着就已经硬了。"
     },
     {
      "type": "text",
      "text": "昨天不是说不要？现在这么乖了？"
     },
     {
      "type": "text",
      "text": "大声点，把‘主人’两个字喊出来。"
     }
    ]
